import React, { useState } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { content } from '../data';
import { Send, MapPin, Phone, Mail, Copy, Check } from 'lucide-react';

const Contact: React.FC = () => {
  const { lang } = useLanguage();
  const t = content[lang].contact;
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const [copied, setCopied] = useState(false);

  // ---------------------------------------------------------
  // Formspree ID provided by user
  // ---------------------------------------------------------
  const FORMSPREE_ID = 'mldqyegp'; 

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setStatus('submitting');
    const form = e.currentTarget;
    const data = new FormData(form);

    try {
      const response = await fetch(`https://formspree.io/f/${FORMSPREE_ID}`, {
        method: 'POST',
        body: data,
        headers: { 'Accept': 'application/json' }
      });
      if (response.ok) {
        setStatus('success');
        form.reset();
      } else {
        setStatus('error');
      }
    } catch (error) {
      setStatus('error');
    }
  };

  const copyEmail = () => {
    navigator.clipboard.writeText('genius@eudaimonia-ip.com');
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="animate-fade-in bg-brand-light min-h-screen py-24">
      <div className="max-w-6xl mx-auto px-6 lg:px-8">

        <div className="text-center mb-16">
          <h1 className="text-4xl font-serif font-bold text-brand-dark mb-4">{t.title}</h1>
          <p className="text-xl text-brand-warm max-w-2xl mx-auto font-light">{t.desc}</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">
          {/* Contact Info - Brand Dark (In dark mode brand-dark is light text, so we inverse explicitly here for contrast if needed, or keep it consistent) */}
          {/* Since brand-dark is now text color (light), we need a specific background color here. Let's use brand-white (Slate 800) */}
          <div className="bg-brand-white text-brand-dark p-12 rounded-[2rem] shadow-xl flex flex-col justify-between relative overflow-hidden min-h-[500px] border border-brand-warm/10">
            {/* Decorative organic shapes */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-brand-primary/10 rounded-full -mr-16 -mt-16 blur-2xl z-0"></div>
            <div className="absolute bottom-0 left-0 w-80 h-80 bg-brand-secondary/10 rounded-full -ml-20 -mb-20 blur-3xl z-0"></div>

            <div className="relative z-10">
              <h3 className="text-3xl font-serif font-medium mb-12">Get in Touch</h3>

              <div className="space-y-10">
                <div className="flex items-start gap-6 group">
                  <div className="bg-brand-light/50 p-4 rounded-xl group-hover:bg-brand-primary transition-colors duration-300 border border-brand-warm/10">
                    <Mail className="text-brand-primary group-hover:text-brand-light transition-colors" size={24} />
                  </div>
                  <div className="flex-1">
                    <p className="text-xs text-brand-warm/60 uppercase tracking-widest mb-1">Email</p>
                    <div className="flex items-center gap-3">
                      <a href="mailto:genius@eudaimonia-ip.com" className="text-xl font-medium hover:text-brand-primary transition-colors font-sans select-all text-brand-dark">
                        genius@eudaimonia-ip.com
                      </a>
                      <button 
                        onClick={copyEmail} 
                        className="p-2 bg-brand-light/50 hover:bg-brand-light rounded-lg transition-colors text-brand-warm hover:text-brand-primary flex items-center justify-center w-8 h-8"
                      >
                        {copied ? <Check size={16} className="text-green-400" /> : <Copy size={16} />}
                      </button>
                    </div>
                  </div>
                </div>

                <div className="flex items-start gap-6 group">
                   <div className="bg-brand-light/50 p-4 rounded-xl group-hover:bg-brand-primary transition-colors duration-300 border border-brand-warm/10">
                    <Phone className="text-brand-primary group-hover:text-brand-light transition-colors" size={24} />
                  </div>
                  <div>
                    <p className="text-xs text-brand-warm/60 uppercase tracking-widest mb-1">Phone</p>
                    <p className="text-xl font-medium font-sans select-all text-brand-dark">+886 963 553 187</p>
                  </div>
                </div>

                <div className="flex items-start gap-6 group">
                   <div className="bg-brand-light/50 p-4 rounded-xl group-hover:bg-brand-primary transition-colors duration-300 border border-brand-warm/10">
                    <MapPin className="text-brand-primary group-hover:text-brand-light transition-colors" size={24} />
                  </div>
                  <div>
                    <p className="text-xs text-brand-warm/60 uppercase tracking-widest mb-1">Office</p>
                    <p className="text-xl font-medium font-sans text-brand-dark">Taipei, Taiwan</p>
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-12 relative z-10 pt-8 border-t border-brand-warm/10">
              <p className="text-sm text-brand-warm font-light">
                We typically reply within 1 business day.
              </p>
            </div>
          </div>

          {/* Form */}
          <div className="bg-brand-white p-12 rounded-[2rem] shadow-lg border border-brand-warm/10">
            {status === 'success' ? (
              <div className="h-full flex flex-col items-center justify-center text-center animate-fade-in">
                <div className="w-20 h-20 bg-green-900/20 rounded-full flex items-center justify-center text-green-400 mb-8 border border-green-500/20">
                  <Send size={32} />
                </div>
                <h3 className="text-3xl font-serif text-brand-dark mb-4">Message Sent!</h3>
                <p className="text-brand-warm mb-8">Thank you for contacting us. We will get back to you shortly.</p>
                <button onClick={() => setStatus('idle')} className="text-brand-primary font-medium hover:underline tracking-wide text-sm uppercase">Send another message</button>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-8 h-full flex flex-col justify-center">
                 {/* Hidden Field for Email Subject */}
                 <input type="hidden" name="_subject" value="New Inquiry from Eudaimonia Website" />

                 {status === 'error' && (
                    <div className="bg-red-900/20 text-red-400 p-4 rounded-lg text-sm text-center border border-red-500/20">
                       Oops! Something went wrong. Please try again.
                    </div>
                 )}

                <div className="space-y-6">
                  {/* Name Input */}
                  <div>
                    <label htmlFor="name" className="block text-xs font-bold text-brand-warm uppercase tracking-wider mb-2">{t.form.name}</label>
                    <input name="name" type="text" id="name" required className="w-full px-0 py-3 bg-transparent border-b border-brand-warm/30 text-brand-dark focus:border-brand-primary outline-none transition-all placeholder-brand-warm/20 text-lg" placeholder="Your Name" />
                  </div>

                  {/* Email Input */}
                  <div>
                    <label htmlFor="email" className="block text-xs font-bold text-brand-warm uppercase tracking-wider mb-2">{t.form.email}</label>
                    <input name="email" type="email" id="email" required className="w-full px-0 py-3 bg-transparent border-b border-brand-warm/30 text-brand-dark focus:border-brand-primary outline-none transition-all placeholder-brand-warm/20 text-lg" placeholder="jane@example.com" />
                  </div>

                  {/* Message Input */}
                  <div>
                    <label htmlFor="message" className="block text-xs font-bold text-brand-warm uppercase tracking-wider mb-2">{t.form.message}</label>
                    <textarea name="message" id="message" rows={4} required className="w-full px-0 py-3 bg-transparent border-b border-brand-warm/30 text-brand-dark focus:border-brand-primary outline-none transition-all resize-none placeholder-brand-warm/20 text-lg" placeholder="How can we help you?"></textarea>
                  </div>
                </div>

                <button 
                  type="submit" 
                  disabled={status === 'submitting'}
                  className="w-full bg-brand-primary text-brand-light py-4 rounded-xl font-bold text-lg hover:bg-white hover:text-brand-light transition-all shadow-[0_0_20px_rgba(34,211,238,0.3)] hover:shadow-[0_0_30px_rgba(34,211,238,0.5)] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed mt-auto"
                >
                  {status === 'submitting' ? 'Sending...' : t.form.submit}
                  {status !== 'submitting' && <Send size={18} />}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Contact;

