                <LogoHorizontal lang={lang} theme="light" />
              </NavLink>
            </div>

            {/* Desktop Menu */}
            <div className="hidden md:flex space-x-8 items-center">
              {navLinks.map((link) => {
                const baseClasses = "text-xs tracking-widest uppercase transition-all duration-300 relative group py-2 font-medium font-mono";

                if (link.type === 'external') {
                  return (
                     <a
                      key={link.to}
                      href={link.to}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={`${baseClasses} text-brand-dark hover:text-brand-primary`}
                    >
                      {link.label}
                      <span className="absolute bottom-0 left-0 w-full h-[1px] bg-brand-primary transform origin-left transition-transform duration-300 scale-x-0 group-hover:scale-x-100"></span>
                    </a>
                  )
                }
                return (
                  <NavLink
                    key={link.to}
                    to={link.to}
                    className={({ isActive }) =>
                      `${baseClasses} ${
                        isActive 
                          ? 'text-brand-primary' 
                          : 'text-brand-dark hover:text-brand-primary'
                      }`
                    }
                  >
                    {({ isActive }) => (
                      <>
                        {link.label}
                        <span className={`absolute bottom-0 left-0 w-full h-[1px] bg-brand-primary transform origin-left transition-transform duration-300 ${isActive ? 'scale-x-100' : 'scale-x-0 group-hover:scale-x-100'}`}></span>
