import React from 'react';

interface GeometricPatternProps {
  seed: string;
  className?: string;
}

const GeometricPattern: React.FC<GeometricPatternProps> = ({ seed, className = "" }) => {
  const getNumber = (str: string, max: number) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    return Math.abs(hash % max);
  };

  // Tech Palette: Cyan, Indigo, Violet, Slate
  const colors = [
    '#22D3EE', // Cyan
    '#818CF8', // Indigo
    '#38BDF8', // Sky
    '#6366F1', // Violet
  ];

  const c1 = colors[getNumber(seed + 'c1', colors.length)];
  const c2 = colors[getNumber(seed + 'c2', colors.length)];

  // Tech: Uses lines and circles instead of blobs
  const x1 = getNumber(seed + 'x1', 100);
  const y1 = getNumber(seed + 'y1', 100);
  const r1 = 10 + getNumber(seed + 'r1', 40);

  const x2 = getNumber(seed + 'x2', 100);
  const y2 = getNumber(seed + 'y2', 100);
  const r2 = 5 + getNumber(seed + 'r2', 30);

  return (
    <div className={`relative overflow-hidden bg-brand-white ${className}`}>
      <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
        <rect width="100" height="100" fill="#1E293B" />

        {/* Grid Background */}
        <defs>
            <pattern id={`grid-${seed}`} width="10" height="10" patternUnits="userSpaceOnUse">
                <path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(148,163,184,0.1)" strokeWidth="0.5"/>
            </pattern>
            <radialGradient id={`glow-${seed}`} cx="50%" cy="50%" r="50%">
                <stop offset="0%" stopColor={c1} stopOpacity="0.3" />
                <stop offset="100%" stopColor={c1} stopOpacity="0" />
            </radialGradient>
        </defs>
        <rect width="100" height="100" fill={`url(#grid-${seed})`} />

        {/* Geometric Elements */}
        <circle cx={x1} cy={y1} r={r1} fill={`url(#glow-${seed})`} />

        {/* Tech Lines */}
        <line x1="0" y1={y1} x2="100" y2={y2} stroke={c1} strokeWidth="0.2" opacity="0.5" />
        <line x1={x1} y1="0" x2={x2} y2="100" stroke={c2} strokeWidth="0.2" opacity="0.5" />

        <circle cx={x2} cy={y2} r={r2/2} stroke={c2} strokeWidth="0.5" fill="none" opacity="0.8" />
        <rect x={x1} y={y2} width={r2/2} height={r2/2} stroke={c1} strokeWidth="0.5" fill="none" opacity="0.6" transform={`rotate(45 ${x1} ${y2})`} />

      </svg>
    </div>
  );
};

export default GeometricPattern;

